@Repository
public interface UserRepository extends JpaRepository<User, Long> {

    // ANTI-PATTERN: Results in N+1 if addresses are accessed lazily in loops,
    // or Cartesian product if joined naively.
    @Query("SELECT u FROM User u JOIN FETCH u.orders")
    List<User> findAllWithOrders();

    // PRODUCTION-GRADE: Use pagination, DTO projections, or explicit batch fetching.
    @Query("SELECT new com.example.dto.UserSummaryDto(u.id, u.username) FROM User u")
    Page<UserSummaryDto> findAllSummaries(Pageable pageable);
}
